<?php $pageTitle='Tasks'; $activePage='tasks'; require_once __DIR__.'/../includes/header.php'; require_permission('manage_tasks'); $tasks=$pdo->query("SELECT t.*,p.name project_name,u.name assignee FROM tasks t JOIN projects p ON p.id=t.project_id LEFT JOIN users u ON u.id=t.assigned_to ORDER BY t.due_date")->fetchAll(); ?><div class="d-flex justify-content-between align-items-end mb-4"><div><span class="section-kicker">Execution</span><h2 class="mt-2">Tasks</h2><p class="text-muted mb-0">Turn milestones into visible, manageable next steps.</p></div><div class="d-flex gap-2"><a href="<?= url('tasks/kanban.php') ?>" class="btn btn-light"><i class="bi bi-kanban me-2"></i>Kanban</a><a href="<?= url('tasks/create.php') ?>" class="btn btn-primary"><i class="bi bi-plus-lg me-2"></i>Add task</a></div></div><div class="table-shell"><div class="table-responsive"><table class="table"><thead><tr><th>Task</th><th>Project</th><th>Assignee</th><th>Priority</th><th>Due date</th><th>Status</th></tr></thead><tbody><?php foreach($tasks as $task): ?><tr><td><span class="table-title"><?= e($task['title']) ?></span><span class="table-subtitle">#TASK-<?= str_pad((string)$task['id'],3,'0',STR_PAD_LEFT) ?></span></td><td><?= e($task['project_name']) ?></td><td><?= e($task['assignee']??'Unassigned') ?></td><td><span class="priority-dot priority-<?= strtolower($task['priority']) ?> me-2 d-inline-block"></span><?= e($task['priority']) ?></td><td><?= e(date('M d, Y',strtotime($task['due_date']))) ?></td><td><span class="status-badge status-<?= strtolower(str_replace(' ','-',$task['status'])) ?>"><?= e($task['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></div><?php require_once __DIR__.'/../includes/footer.php'; ?>
